const fs = require("fs");
const path = require("path");

const KEY_RE = /^[0-9]+-[a-f0-9]{64}\.(pdf|docx|png|jpg)$/;

function baseDir() {
  return path.resolve(process.env.STORAGE_DIR || path.join(__dirname, "..", "..", "..", ".storage"));
}

/** Keys are generated by this module only; anything else (traversal included) is refused. */
function assertKey(key) {
  if (typeof key !== "string" || !KEY_RE.test(key)) {
    const err = new Error("Invalid storage key");
    err.code = "INVALID_KEY";
    throw err;
  }
  return key;
}

function fileFor(key) {
  assertKey(key);
  const base = baseDir();
  const full = path.join(base, key);
  if (path.dirname(full) !== base) {
    const err = new Error("Invalid storage key");
    err.code = "INVALID_KEY";
    throw err;
  }
  return full;
}

async function put(key, buf) {
  const file = fileFor(key);
  await fs.promises.mkdir(baseDir(), { recursive: true, mode: 0o700 });
  await fs.promises.writeFile(file, buf, { mode: 0o600 });
}

async function get(key) {
  return fs.promises.readFile(fileFor(key));
}

async function remove(key) {
  try {
    await fs.promises.unlink(fileFor(key));
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }
}

module.exports = { put, get, remove, assertKey, KEY_RE };
